// Super Sketch service worker: saves the whole app on the device so it works without wifi.
// The file list between the markers is generated by `node scripts/precache.mjs` — re-run it when files change.
const VERSION = 'v3';
const CACHE = `supersketch-${VERSION}`;

/* PRECACHE:START */
const CORE = [
  "/",
  "/icons/icon-180.png",
  "/icons/icon-512.png",
  "/icons/icon.svg",
  "/index.html",
  "/manifest.webmanifest",
  "/src/builders.js",
  "/src/colour.js",
  "/src/drawings.js",
  "/src/drawings_more.js",
  "/src/drawings_more2.js",
  "/src/games.js",
  "/src/glyphs.js",
  "/src/grownups.js",
  "/src/main.js",
  "/src/mixup.js",
  "/src/reader.js",
  "/src/shapes.js",
  "/src/sound.js",
  "/src/stickers.js",
  "/src/store.js",
  "/src/stories.js",
  "/src/styles.css",
  "/src/tracer.js",
  "/src/util.js"
];
/* PRECACHE:END */

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(CORE)).then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('supersketch-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

// Online: always fetch the freshest copy (and refresh the saved one). Offline / slow: use the saved copy.
self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const fromCache = () => cache.match(req, { ignoreSearch: true }).then((r) => r || (req.mode === 'navigate' ? cache.match('/index.html') : undefined));
    try {
      const res = await Promise.race([
        fetch(req),
        new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), 4000)),
      ]);
      if (res && res.ok) cache.put(req, res.clone());
      return res;
    } catch {
      return (await fromCache()) || Response.error();
    }
  })());
});
